let actionOrigin='activity',selectedAction=null,activitySort=-1,streamTimer=null,streamSequence=0,streamPoints=[];
const copyIcon='<svg viewBox="0 0 20 20" aria-hidden="true"><rect x="7" y="6" width="9" height="11" rx="2"/><path d="M12 6V4a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h2"/></svg>';
function tagList(ids){return ids.map(k=>`<button class="action-tag" style="--tag:${actionColor(k)}" data-action="${k}">${esc(name(k))}</button>`).join('')}
function addressCell(address){return address?`<span class="address-cell"><a href="https://hsk.blockscout.com/address/${esc(address)}" target="_blank" rel="noopener" title="${esc(address)}">${short(address)}</a><button class="copy-button" data-copy="${esc(address)}" aria-label="Copy address ${esc(address)}" title="Copy address">${copyIcon}</button></span>`:'<span class="muted">Contract creation</span>'}
function transactionTable(list){return `<div class="table-scroll ledger"><table><thead><tr><th><button data-sort-time>Date ${activitySort<0?'↓':'↑'}</button></th><th>Transaction</th><th>Actions</th><th>Method</th><th>From</th><th></th><th>To</th><th>Value <small>HSK</small></th><th>Status</th></tr></thead><tbody>${list.map(t=>{const s=t.state;return `<tr><td class="date-cell">${txDate(t)}<small>${s.transaction.timestamp.slice(11,19)} UTC</small></td><td><span class="address-cell"><button data-evidence="${t.id}" class="hash-link">${short(t.id)}</button><button class="copy-button" data-copy="${t.id}" aria-label="Copy transaction hash ${t.id}" title="Copy hash">${copyIcon}</button></span></td><td class="action-cell"><div class="tags-inline">${tagList(chosen(t))||'<span class="muted">Unclassified</span>'}</div></td><td><span class="method-chip" title="${esc(s.transaction.method||'')}">${esc(s.transaction.method||'—')}</span></td><td>${addressCell(s.from)}</td><td><span class="transfer-arrow">→</span></td><td>${addressCell(s.to)}</td><td class="value-cell">${esc(amount(s.transaction.value))}</td><td><span class="status-dot ${s.transaction.status==='ok'?'success':'failure'}" title="${esc(s.transaction.status)}"></span>${s.transaction.status==='ok'?'Success':'Failed'}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty">No matching transactions.</td></tr>'}</tbody></table></div>`}
function openAction(id){if(view!=='action')actionOrigin=view==='analysis'?'analysis':'activity';selectedAction=id;changeView('action');history.replaceState(null,'','#action?id='+id)}
function renderAction(){if(!label(selectedAction)){selectedAction=labels()[0].id}const list=rows().filter(t=>chosen(t).includes(selectedAction)&&actionContextMatches(t)).sort((a,b)=>activitySort*a.state.transaction.timestamp.localeCompare(b.state.transaction.timestamp)),related={};list.forEach(t=>chosen(t).filter(k=>k!==selectedAction).forEach(k=>related[k]=(related[k]||0)+1));$('#action-header').innerHTML=`<div class="category-heading"><div><button class="back-link" data-back-view="${actionOrigin}">← ${actionOrigin==='analysis'?'Analysis':'Activity'}</button><h1><i style="background:${actionColor(selectedAction)}"></i>${esc(name(selectedAction))}</h1></div><span><b>${list.length}</b> transactions</span></div>${actionContextMarkup()}<div class="related-actions"><span>Related actions</span>${tagList(Object.keys(related).sort((a,b)=>related[b]-related[a]).slice(0,6))||'<span class="muted">None</span>'}</div>`;$('#action-content').innerHTML=transactionTable(list)}
function activityMatches(t,dates=true){const s=t.state,q=$('#activity-search').value.toLowerCase().trim(),a=$('#activity-action').value,status=$('#activity-status').value,d=txDate(t);return(!a||chosen(t).includes(a))&&(!status||(status==='ok'?s.transaction.status==='ok':s.transaction.status!=='ok'))&&(!q||[t.id,s.from,s.to,s.transaction.method].join(' ').toLowerCase().includes(q))&&(!dates||((!$('#date-start').value||d>=$('#date-start').value)&&(!$('#date-end').value||d<=$('#date-end').value)))}
function resetActivity(){activityPage=0;['date-start','date-end','activity-search'].forEach(id=>$('#'+id).value='');$('#activity-status').value='';$('#activity-action').innerHTML='<option value="">All actions</option>'+labels().map(l=>`<option value="${l.id}">${esc(l.label)}</option>`).join('');startField();if(view==='activity')renderActivity()}
function choosePeriod(d){$('#date-start').value=d;$('#date-end').value=periodEnd(d,$('#time-unit').value);activityPage=0;renderActivity()}
function renderActivity(){if(!data)return;const all=[...rows()].sort((a,b)=>txDate(a).localeCompare(txDate(b))),unit=$('#time-unit').value,context=all.filter(t=>activityMatches(t,false)),filtered=all.filter(t=>activityMatches(t)),bins=[];for(let d=periodStart(txDate(all[0]),unit);d<=periodStart(txDate(all.at(-1)),unit);d=nextPeriod(d,unit))bins.push(d);
 const invalidRange=$('#date-start').value&&$('#date-end').value&&$('#date-start').value>$('#date-end').value;$('#activity-filter-error').hidden=!invalidRange;$('#activity-filter-error').textContent=invalidRange?'Start date must be on or before end date.':'';$('#date-start').setAttribute('aria-invalid',String(!!invalidRange));$('#date-end').setAttribute('aria-invalid',String(!!invalidRange));
 $('#activity-count').textContent=`${filtered.length} transactions`;$('#time-range').textContent=`${txDate(all[0])} — ${txDate(all.at(-1))}`;
 const sorted=[...filtered].sort((a,b)=>activitySort*a.state.transaction.timestamp.localeCompare(b.state.transaction.timestamp)),pages=Math.max(1,Math.ceil(sorted.length/25));activityPage=Math.min(activityPage,pages-1);$('.activity-table').innerHTML=transactionTable(sorted.slice(activityPage*25,(activityPage+1)*25));if(invalidRange)$('.activity-table .empty').textContent='Choose a valid date range.';$('#activity-table-count').innerHTML='<button class="download-button" id="download-data">↓ Export CSV</button>';$('#download-data').onclick=()=>exportTransactions(sorted);$('#activity-page').textContent=`${filtered.length?activityPage*25+1:0}–${Math.min((activityPage+1)*25,filtered.length)} of ${filtered.length}`;$('#activity-prev').disabled=activityPage===0;$('#activity-next').disabled=activityPage>=pages-1;
}
function renderTrend(bins,txs,unit){const top=labels().map(l=>({...l,n:txs.filter(t=>chosen(t).includes(l.id)).length})).filter(l=>l.n).sort((a,b)=>b.n-a.n).slice(0,6),series=top.map(l=>bins.map(d=>txs.filter(t=>chosen(t).includes(l.id)&&periodStart(txDate(t),unit)===d).length)),max=Math.max(1,...series.flat()),W=1100,H=200,L=32,R=1080,T=16,B=172,x=i=>L+i*(R-L)/Math.max(1,bins.length-1),y=n=>B-n/max*(B-T);let svg=`<defs>${top.map((l,i)=>`<linearGradient id="trend-${i}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${actionColor(l.id)}" stop-opacity=".13"/><stop offset="1" stop-color="${actionColor(l.id)}" stop-opacity="0"/></linearGradient>`).join('')}</defs>`;
 for(let i=0;i<3;i++){const yy=T+(B-T)*i/2;svg+=`<path d="M${L},${yy}H${R}" stroke="#e6ebf1" stroke-dasharray="2 5"/><text x="0" y="${yy+4}" class="axis-label">${Math.round(max*(1-i/2))}</text>`}top.forEach((l,j)=>{const d=series[j].map((n,i)=>`${i?'L':'M'}${x(i)},${y(n)}`).join(' ');svg+=`<path d="${d}L${R},${B}L${L},${B}Z" fill="url(#trend-${j})"/><path d="${d}" stroke="${actionColor(l.id)}" stroke-width="2" fill="none" stroke-linejoin="round" stroke-linecap="round"/>`;series[j].forEach((n,i)=>{if(n)svg+=`<circle cx="${x(i)}" cy="${y(n)}" r="4" fill="white" stroke="${actionColor(l.id)}" stroke-width="1.5"/>`})});bins.forEach((d,i)=>svg+=`<rect data-period="${d}" role="button" tabindex="0" aria-label="Filter ${d}" x="${x(i)-(R-L)/Math.max(1,bins.length-1)/2}" y="0" width="${(R-L)/Math.max(1,bins.length-1)}" height="${H}" fill="transparent"/>`);
 $('#timeline').innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Action frequency over time">${svg}</svg>`;$('#time-axis').innerHTML=bins.map((d,i)=>`<span>${bins.length<19||i%Math.ceil(bins.length/10)===0?d.slice(2,7):''}</span>`).join('');$('#time-legend').innerHTML=tagList(top.map(l=>l.id));document.querySelectorAll('[data-period]').forEach(e=>{bindSvg(e,()=>choosePeriod(e.dataset.period));tooltip(e,`${e.dataset.period} · ${txs.filter(t=>periodStart(txDate(t),unit)===e.dataset.period).length} transactions`)})
}
function renderMatrix(bins,txs,unit){const from=$('#date-start').value,to=$('#date-end').value,visible=bins.filter(d=>(!from||periodEnd(d,unit)>=from)&&(!to||d<=to)),top=labels().map(l=>({...l,n:txs.filter(t=>chosen(t).includes(l.id)).length})).filter(l=>l.n).sort((a,b)=>b.n-a.n).slice(0,10),values=top.map(l=>visible.map(d=>txs.filter(t=>chosen(t).includes(l.id)&&periodStart(txDate(t),unit)===d).length)),max=Math.max(1,...values.flat());if(!top.length){$('#time-heatmap').innerHTML='<div class="empty">No activity in this range.</div>';return}$('#time-heatmap').innerHTML=`<div class="matrix-layout" style="--cols:${visible.length}"><div class="matrix-corner"></div><div class="matrix-dates">${visible.map((d,i)=>`<span>${visible.length<=18||i%Math.ceil(visible.length/12)===0?d.slice(2,7):''}</span>`).join('')}</div><div class="matrix-labels">${top.map(l=>`<button data-action="${l.id}"><i style="background:${actionColor(l.id)}"></i>${esc(l.label)}</button>`).join('')}</div><div class="matrix-cells">${top.map((l,i)=>visible.map((d,j)=>`<button class="matrix-cell" data-heat-label="${l.id}" data-heat-date="${d}" style="--cell:${actionColor(l.id)};--strength:${values[i][j]?18+82*Math.sqrt(values[i][j]/max):0}%" aria-label="${esc(l.label)} · ${d} · ${values[i][j]} transactions"></button>`).join('')).join('')}</div></div>`;document.querySelectorAll('[data-heat-label]').forEach(b=>{b.onclick=()=>{$('#activity-action').value=b.dataset.heatLabel;choosePeriod(b.dataset.heatDate)};tooltip(b,b.getAttribute('aria-label'))})}
function exportTransactions(list){const fields=['hash','timestamp','actions','method','from','to','value_hsk','status'],lines=list.map(t=>[t.id,t.state.transaction.timestamp,chosen(t).map(name).join('; '),t.state.transaction.method,t.state.from,t.state.to,amount(t.state.transaction.value),t.state.transaction.status]);const csv=[fields,...lines].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='hsk-action-scan.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function startStream(){if(streamTimer)return;for(let i=0;i<24;i++)streamPoints.push({time:Date.now()-(24-i)*2400,t:rows()[(i*17)%rows().length],n:chosen(rows()[(i*17)%rows().length]).length});drawStream();streamTimer=setInterval(()=>{if(document.hidden)return;const t=rows()[(streamSequence++*17)%rows().length];streamPoints.push({time:Date.now(),t,n:chosen(t).length});streamPoints=streamPoints.slice(-48);drawStream()},2400)}
function drawStream(){const W=820,H=108,B=91,x=i=>i*W/Math.max(1,streamPoints.length-1),y=n=>B-12-n*15,d=streamPoints.map((p,i)=>`${i?'L':'M'}${x(i)},${y(p.n)}`).join(' '),last=streamPoints.at(-1);$('#stream-clock').textContent=new Date(last.time).toLocaleTimeString('en-GB',{hour12:false});$('#stream-plot').innerHTML=`<svg viewBox="0 0 ${W} ${H}" aria-label="Simulated incoming action stream"><defs><linearGradient id="stream-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#7393b8" stop-opacity=".2"/><stop offset="1" stop-color="#7393b8" stop-opacity="0"/></linearGradient></defs><path d="M0 ${B}H${W}" stroke="#e8edf3"/><path d="${d}L${W},${B}L0,${B}Z" fill="url(#stream-fill)"/><path d="${d}" fill="none" stroke="#6688b1" stroke-width="1.7" stroke-linejoin="round"/>${streamPoints.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.n)}" r="${i===streamPoints.length-1?4:2}" fill="${actionColor(chosen(p.t)[0])}"/>`).join('')}</svg>`;$('#stream-events').innerHTML=streamPoints.slice(-2).reverse().map(p=>`<div class="stream-event"><span class="stream-time">${new Date(p.time).toLocaleTimeString('en-GB',{hour12:false})}</span><div>${tagList(chosen(p.t).slice(0,3))||'<span class="muted">Unclassified</span>'}</div><button data-evidence="${p.t.id}" title="Open source transaction">↗</button></div>`).join('')}

document.addEventListener('click',async e=>{const tag=e.target.closest('[data-action]'),copy=e.target.closest('[data-copy]'),tx=e.target.closest('[data-evidence]');if(tag)openAction(tag.dataset.action);if(tx)openEvidence(tx.dataset.evidence);const back=e.target.closest('[data-back-view]');if(back)changeView(back.dataset.backView);if(e.target.closest('[data-sort-time]')){activitySort*=-1;view==='action'?renderAction():renderActivity()}if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);copy.classList.add('copied');copy.title='Copied';$('#toast').textContent='Address or hash copied';$('#toast').hidden=false;setTimeout(()=>{copy.classList.remove('copied');$('#toast').hidden=true},1600)}catch{$('#toast').textContent='Copy unavailable. Select the address to copy.';$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,2500)}}});
$('.cloud-wrap').addEventListener('click',e=>{if(!e.target.closest('[data-word],button'))setLabels([])});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&view==='analysis')setLabels([])});$('#open-activity').onclick=()=>changeView('activity');['date-start','date-end','activity-action','activity-status','time-unit'].forEach(id=>$('#'+id).onchange=()=>{activityPage=0;renderActivity()});$('#activity-search').oninput=()=>{activityPage=0;renderActivity()};$('#activity-reset').onclick=resetActivity;$('#activity-prev').onclick=()=>{activityPage--;renderActivity()};$('#activity-next').onclick=()=>{activityPage++;renderActivity()};
